namespace Models {
    public class Counter {
        private int value;
        private Counter(int initial) { value = initial; }
        public static Counter Create(int value = 1) => new Counter(value);
        private int Step(int amount) { value += amount; return value; }
        public int Add(int amount = 1) => Step(amount);
        public long Add(long amount) => value + amount;
        public int Combine(int first, int second) => first * 10 + second;
    }
}
void Main() {
    Models.Counter c = Models.Counter.Create(); Print(c.Add()); Print(c.Add(3L));
    var n = 0; Print(c.Combine(second: n++, first: ++n)); Print(n);
}
